param([string]$InputJson, [string]$OutDir)
$ErrorActionPreference='Stop'
$data=Get-Content -Raw -Encoding UTF8 $InputJson | ConvertFrom-Json
New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
$scriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path
$work=Join-Path $scriptDir 'video_work'
New-Item -ItemType Directory -Force -Path $work | Out-Null
Add-Type -AssemblyName System.Speech
$synth=New-Object System.Speech.Synthesis.SpeechSynthesizer
$voices=$synth.GetInstalledVoices()
if($voices.VoiceInfo.Name -contains 'Microsoft David Desktop'){$synth.SelectVoice('Microsoft David Desktop')}
$synth.Rate=0;$synth.Volume=100
$ffmpeg='C:\Users\skala\AppData\Local\Microsoft\WinGet\Packages\Gyan.FFmpeg_Microsoft.Winget.Source_8wekyb3d8bbwe\ffmpeg-9.0.2-full_build\bin\ffmpeg.exe'
$edge='C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'
$html=@'
<!doctype html><html><meta charset="utf-8"><style>*{box-sizing:border-box}html,body{margin:0;width:1600px;height:900px;overflow:hidden;background:#08110f;color:#f5faf4;font-family:Arial,'Segoe UI',sans-serif}body{position:relative;padding:78px 96px;background:radial-gradient(ellipse at 85% 15%,#204738 0,transparent 32%),radial-gradient(ellipse at 10% 95%,#152c25 0,transparent 40%),#08110f}.ring{position:absolute;right:-190px;top:-300px;width:800px;height:800px;border-radius:50%;border:1px solid #35534266;box-shadow:0 0 0 64px #35534222,0 0 0 128px #35534217,0 0 0 192px #35534210}.top{position:relative;display:flex;align-items:center;gap:16px;color:#c6f26b;font-size:23px;font-weight:bold;letter-spacing:2px}.logo{width:54px;height:54px;border-radius:17px;background:#c6f26b;color:#0b2b25;display:grid;place-items:center;font-size:21px}.count{margin-left:auto;color:#9eb2a7;font-size:18px;letter-spacing:0;font-weight:500}.title{position:relative;margin-top:100px;max-width:1330px;font-size:70px;line-height:1.08;font-weight:750;letter-spacing:-2px}.tag{position:relative;margin-top:24px;color:#bbcdc2;font-size:27px;line-height:1.45;max-width:1120px}.cards{position:relative;margin-top:72px;display:grid;grid-template-columns:1fr 1fr;gap:22px;max-width:1250px}.card{min-height:116px;padding:22px 25px;border-radius:24px;border:1px solid #56726366;background:#13231fdd;font-size:23px;line-height:1.28;display:flex;align-items:center;gap:18px}.dot{height:13px;width:13px;flex:none;border-radius:50%;background:#c6f26b;box-shadow:0 0 24px #c6f26b88}.bottom{position:absolute;left:96px;right:96px;bottom:54px;display:flex;align-items:center;justify-content:space-between;color:#8da399;font-size:17px;letter-spacing:1px}.progress{height:5px;background:#c6f26b;position:absolute;left:0;bottom:0;width:PROGRESS%}</style><body><div class="ring"></div><div class="top"><div class="logo">VT</div><span>VOKATRACK</span><span class="count">SLIDE / TOTAL</span></div><div class="title">TITLE</div><div class="tag">TAGLINE</div><div class="cards">CARDS</div><div class="bottom"><span>PKL TERINTEGRASI · SEKOLAH × INDUSTRI</span><span>INDONESIA · 2026</span></div><div class="progress"></div></body></html>
'@
function EscapeHtml([string]$s){[System.Net.WebUtility]::HtmlEncode($s)}
$concat=Join-Path $work 'concat.txt';$rows=@();$i=0;$durations=@();$wavFiles=@();$pngFiles=@()
foreach($slide in $data.slides){$i++;$stem=Join-Path $work ('slide-{0:D2}' -f $i);$text=$slide.narration.Replace('&','dan').Replace('—',',').Replace('–',' sampai ').Replace('VokaTrack','Voka Track');$wav=$stem+'.wav';$synth.SetOutputToWaveFile($wav);[void]$synth.Speak($text);$synth.SetOutputToNull();$wavFiles+=$wav
 $cards='';foreach($point in $slide.points){$cards+='<div class="card"><i class="dot"></i><span>'+(EscapeHtml $point)+'</span></div>'};$pageHtml=$html.Replace('TITLE',(EscapeHtml $slide.title)).Replace('TAGLINE',(EscapeHtml $slide.tagline)).Replace('CARDS',$cards).Replace('SLIDE',($i.ToString('00'))).Replace('TOTAL',$data.slides.Count.ToString('00')).Replace('PROGRESS',[math]::Round($i*100/$data.slides.Count,2).ToString([cultureinfo]::InvariantCulture));$page=Join-Path $work 'card.html';Set-Content $page $pageHtml -Encoding UTF8;$png=$stem+'.png';$url='file:///'+($page -replace '\\','/');& $edge '--headless=new' '--disable-gpu' '--hide-scrollbars' '--no-first-run' '--disable-extensions' '--force-device-scale-factor=1' '--window-size=1600,900' "--screenshot=$png" $url 2>$null|Out-Null;if(!(Test-Path $png)){throw "Frame render failed at slide $i"};$pngFiles+=$png
 $probe=& $ffmpeg -i $wav 2>&1|Out-String;$dur=8.0;if($probe -match 'Duration: (\d+):(\d+):(\d+\.\d+)'){$dur=[double]$Matches[1]*3600+[double]$Matches[2]*60+[double]$Matches[3]};$durations+=$dur;$segment=($dur+1.2).ToString('0.000',[cultureinfo]::InvariantCulture);$rows+="file '$($png.Replace('\','/'))'";$rows+="duration $segment";Write-Output "Rendered slide $i / $($data.slides.Count)"
}
$rows+="file '$($pngFiles[-1].Replace('\','/'))'";Set-Content $concat $rows -Encoding ASCII
$silent=Join-Path $work 'silent.mp4';& $ffmpeg -y -f concat -safe 0 -i $concat -r 24 -c:v libx264 -preset fast -pix_fmt yuv420p -vf 'scale=1600:900,format=yuv420p' $silent;if($LASTEXITCODE -ne 0){throw 'Frame encoding failed'}
$audioList=Join-Path $work 'audio.txt';$audios=@();$i=0;foreach($wav in $wavFiles){$i++;$a=Join-Path $work ('padded-{0:D2}.wav' -f $i);& $ffmpeg -y -i $wav -af 'apad=pad_dur=1.2' -ar 44100 -ac 2 $a 2>$null;$audios+=$a};Set-Content $audioList ($audios|ForEach-Object{"file '$($_.Replace('\','/'))'"}) -Encoding ASCII;$joined=Join-Path $work 'narration.wav';& $ffmpeg -y -f concat -safe 0 -i $audioList -c:a pcm_s16le $joined 2>$null
$final=Join-Path $OutDir 'Presentasi-VokaTrack-Bernarasi.mp4';& $ffmpeg -y -i $silent -i $joined -map 0:v -map 1:a -c:v copy -c:a aac -b:a 160k -shortest -movflags +faststart $final;if($LASTEXITCODE -ne 0){throw 'Audio mux failed'}
$md=@('# Naskah Presentasi Video VokaTrack','','Disusun berdasarkan UI dan fitur yang tersedia pada proyek.','');$i=0;$srt=@();$time=0.0;foreach($slide in $data.slides){$i++;$md+=('## {0}. {1}' -f $i,$slide.title);$md+='';$md+=$slide.narration;$md+='';$start=[TimeSpan]::FromSeconds($time).ToString('hh\:mm\:ss\,fff');$time+=$durations[$i-1]+1.2;$end=[TimeSpan]::FromSeconds($time).ToString('hh\:mm\:ss\,fff');$srt+="$i";$srt+="$start --> $end";$srt+=$slide.narration;$srt+=''}
Set-Content (Join-Path $OutDir 'Naskah-Narasi-VokaTrack.md') $md -Encoding UTF8;Set-Content (Join-Path $OutDir 'Subtitle-VokaTrack.srt') $srt -Encoding UTF8
$info=Get-Item $final;Write-Output ('VIDEO='+$final);Write-Output ('SIZE_MB={0:N1}' -f ($info.Length/1MB));Write-Output ('SLIDES='+$data.slides.Count)
